function load(){try{const saved=JSON.parse(localStorage.getItem('myfit-data')||'{}'),d={...DEFAULT,...saved};const demo=[{id:'p1',exerciseId:'e1',sets:4,reps:8,rest:90},{id:'p2',exerciseId:'e2',sets:3,reps:10,rest:90},{id:'p3',exerciseId:'e3',sets:3,reps:10,rest:60},{id:'p4',exerciseId:'e4',sets:3,reps:12,rest:60}];if(!d.history.length&&JSON.stringify(d.plans?.[TODAY()])===JSON.stringify(demo))delete d.plans[TODAY()];const fake=[['Oct 01',72.8],['Oct 08',72.5],['Oct 15',72.2],['Oct 22',72.6],['Oct 29',71.9],['Nov 05',71.6]];d.weighIns=(d.weighIns||[]).filter(w=>!fake.some(([date,weight])=>w.date===date&&w.weight===weight));const muscles={Quads:'ขา',Hamstrings:'ขาด้านหลัง',Chest:'อก',Back:'หลัง',Shoulders:'ไหล่',Core:'แกนกลางลำตัว',Arms:'แขน',Glutes:'ก้น'},gear={Barbell:'บาร์เบล',Dumbbells:'ดัมเบล',Bodyweight:'ใช้น้ำหนักตัว','Cable machine':'เครื่องเคเบิล'},level={Beginner:'เริ่มต้น',Intermediate:'ปานกลาง'},descriptions={e1:SEED[0].description,e2:SEED[1].description,e3:SEED[2].description,e4:SEED[3].description,e5:SEED[4].description,e6:SEED[5].description};d.exercises=(d.exercises||SEED).map(e=>({...e,muscle:muscles[e.muscle]||e.muscle,equipment:gear[e.equipment]||e.equipment,level:level[e.level]||e.level,description:descriptions[e.id]&&["Keep your chest proud, brace your core, and descend until your thighs reach parallel.","Hinge at the hips with a soft bend in the knees. Keep the bar close to your legs.","Lower the dumbbells under control, then press smoothly back over your chest.","Pull your elbows down toward your ribs. Avoid swinging your torso.","Press overhead while keeping your ribs stacked over your hips.","Keep your body in a straight line and breathe steadily throughout the hold."].includes(e.description)?descriptions[e.id]:e.description,unit:e.unit==='sec'?'วินาที':e.unit}));return d}catch{return DEFAULT}}
function openMediaDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open('myfit-media',1);r.onupgradeneeded=()=>r.result.createObjectStore('files');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function saveMedia(file){const db=await openMediaDB(),key='m-'+crypto.randomUUID();return new Promise((resolve,reject)=>{const tx=db.transaction('files','readwrite');tx.objectStore('files').put(file,key);tx.oncomplete=()=>resolve('idb:'+key);tx.onerror=()=>reject(tx.error)})}
function Youtube({video}){const id=(()=>{try{const u=new URL(video);if(u.hostname.includes('youtu.be'))return u.pathname.slice(1);if(u.hostname.includes('youtube.com'))return u.searchParams.get('v')||u.pathname.split('/').filter(Boolean).at(-1)}catch{}return ''})();return id?<div className="youtube-frame"><iframe src={'https://www.youtube-nocookie.com/embed/'+encodeURIComponent(id)} title="วิดีโอสาธิต" loading="lazy" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowFullScreen/></div>:<a className="youtube-link" href={video} target="_blank" rel="noreferrer">เปิดวิดีโอ YouTube</a>}
function Media({src,name,video=false}){const [url,setUrl]=useState('');useEffect(()=>{let objectUrl;if(!src){setUrl('');return}if(!src.startsWith('idb:')){setUrl(src);return}let alive=true;openMediaDB().then(db=>new Promise(resolve=>{const r=db.transaction('files').objectStore('files').get(src.slice(4));r.onsuccess=()=>resolve(r.result)})).then(blob=>{if(blob&&alive){objectUrl=URL.createObjectURL(blob);setUrl(objectUrl)}});return()=>{alive=false;if(objectUrl)URL.revokeObjectURL(objectUrl)}},[src]);return video?(url?<video className="exercise-video" controls playsInline src={url}/>:null):(url?<img className="exercise-media-image" src={url} alt={name}/>:null)}
