function AuthScreen(){const[mode,setMode]=useState('signin'),[email,setEmail]=useState(''),[password,setPassword]=useState(''),[busy,setBusy]=useState(false),[message,setMessage]=useState('');const submit=async e=>{e.preventDefault();setMessage('');setBusy(true);try{if(mode==='signup'){const{data,error}=await supabase.auth.signUp({email:email.trim(),password});if(error)throw error;setMessage(data.session?'สมัครบัญชีสำเร็จ':'สมัครแล้ว กรุณาตรวจอีเมลเพื่อยืนยันบัญชี')}else{const{error}=await supabase.auth.signInWithPassword({email:email.trim(),password});if(error)throw error}}catch(error){setMessage(authError(error))}finally{setBusy(false)}};return <div className="auth-screen"><form className="auth-card" onSubmit={submit}><div className="auth-brand"><span className="brand-icon"><Activity/></span><b>myfit<span>.</span></b></div><div className="eyebrow">พื้นที่ออกกำลังกายส่วนตัว</div><h1>{mode==='signup'?'สร้างบัญชี MyFit':'ยินดีต้อนรับกลับ'}</h1><p>{mode==='signup'?'สมัครเพื่อเก็บแผนและความคืบหน้าไว้กับบัญชี ใช้ต่อได้ทุกอุปกรณ์':'เข้าสู่ระบบเพื่อดูแผนและความคืบหน้าของคุณ'}</p><label>อีเมล<input type="email" required autoComplete="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="you@example.com"/></label><label>รหัสผ่าน<input type="password" required minLength="6" autoComplete={mode==='signup'?'new-password':'current-password'} value={password} onChange={e=>setPassword(e.target.value)} placeholder="อย่างน้อย 6 ตัวอักษร"/></label>{message&&<div className="auth-message" role="status">{message}</div>}<button className="lime-button auth-submit" disabled={busy}>{busy?'กำลังดำเนินการ…':mode==='signup'?'สมัครบัญชี':'เข้าสู่ระบบ'}</button><button type="button" className="auth-toggle" onClick={()=>{setMode(mode==='signup'?'signin':'signup');setMessage('')}}>{mode==='signup'?'มีบัญชีแล้ว? เข้าสู่ระบบ':'ยังไม่มีบัญชี? สมัครสมาชิก'}</button><small>ข้อมูลบัญชีของคุณจะแยกจากผู้ใช้อื่น</small></form></div>}
function authError(error){const m=String(error?.message||'');if(/invalid login credentials/i.test(m))return'อีเมลหรือรหัสผ่านไม่ถูกต้อง';if(/user already registered/i.test(m))return'อีเมลนี้มีบัญชีแล้ว กรุณาเข้าสู่ระบบ';if(/password should be at least/i.test(m))return'รหัสผ่านต้องมีอย่างน้อย 6 ตัวอักษร';if(/email not confirmed/i.test(m))return'กรุณายืนยันอีเมลก่อนเข้าสู่ระบบ';if(/rate limit/i.test(m))return'ลองใหม่อีกครั้งในอีกสักครู่';return m||'ทำรายการไม่สำเร็จ กรุณาลองใหม่'}
