 const [accountReady,setAccountReady]=useState(!user),[cloudError,setCloudError]=useState(''),[syncStatus,setSyncStatus]=useState(user?'loading':'local');const userStorageKey=user?`myfit-data:${user.id}`:'myfit-data';useEffect(()=>{if(!user){setAccountReady(true);setSyncStatus('local');return}let cancelled=false;setAccountReady(false);setCloudError('');setSyncStatus('loading');(async()=>{try{const{data:row,error}=await supabase.from('myfit_user_data').select('data').eq('user_id',user.id).maybeSingle();if(error)throw error;let initial;if(row?.data)initial={...DEFAULT,...row.data,profile:{...DEFAULT.profile,...row.data.profile},settings:{...DEFAULT.settings,...row.data.settings}};else{const localKey=`myfit-data:${user.id}`,hasAccountLocal=localStorage.getItem(localKey),legacy=localStorage.getItem('myfit-data'),migrated=localStorage.getItem('myfit-legacy-migrated')==='true';initial=hasAccountLocal?load(localKey):legacy&&!migrated?load('myfit-data'):DEFAULT;const{error:writeError}=await supabase.from('myfit_user_data').upsert({user_id:user.id,data:initial,updated_at:new Date().toISOString()});if(writeError)throw writeError;if(legacy&&!migrated){localStorage.setItem('myfit-legacy-migrated','true');localStorage.removeItem('myfit-data')}}if(cancelled)return;setDb(initial);localStorage.setItem(`myfit-data:${user.id}`,JSON.stringify(initial));setSyncStatus('synced');setAccountReady(true)}catch(error){if(cancelled)return;setCloudError(error.message||'เชื่อมต่อฐานข้อมูลไม่สำเร็จ');setSyncStatus('error')}})();return()=>{cancelled=true}},[user?.id]);useEffect(()=>{if(!accountReady)return;try{localStorage.setItem(userStorageKey,JSON.stringify(db))}catch{}if(!user)return;let cancelled=false;setSyncStatus('syncing');const id=setTimeout(async()=>{const{error}=await supabase.from('myfit_user_data').upsert({user_id:user.id,data:db,updated_at:new Date().toISOString()});if(!cancelled)setSyncStatus(error?'error':'synced')},650);return()=>{cancelled=true;clearTimeout(id)}},[db,user?.id,accountReady]);useEffect(()=>{if(!toast)return;const id=setTimeout(()=>setToast(''),2200);return()=>clearTimeout(id)},[toast]);useEffect(()=>{if(!timerOn)return;const id=setInterval(()=>setSeconds(s=>Math.max(0,s-1)),1000);return()=>clearInterval(id)},[timerOn]);useEffect(()=>{if(seconds===0&&timerOn){setTimerOn(false);if(db.settings.sound)try{const c=new AudioContext(),o=c.createOscillator();o.connect(c.destination);o.start();o.stop(c.currentTime+.25)}catch{}}},[seconds,timerOn,db.settings.sound]);
 const save=(fn,msg='บันทึกข้อมูลแล้ว')=>{setDb(d=>fn(d));setToast(msg)};const todayPlan=db.plans[TODAY()]||[];const active=db.active;const periodHistory=db.history.filter(h=>!db.progressCycleStart||h.date>=db.progressCycleStart);const ex=id=>db.exercises.find(e=>e.id===id)||db.exercises[0];const doneCount=Object.values(active?.done||{}).flat().filter(Boolean).length;const setTotal=todayPlan.reduce((n,p)=>n+p.sets,0);const workoutCount=db.history.length;const streak=(()=>{const days=[...new Set(db.history.map(h=>h.date))].sort().reverse();if(!days.length)return 0;let n=0,d=new Date(days[0]+'T00:00:00'),today=new Date(TODAY()+'T00:00:00');if((today-d)/86400000>1)return 0;for(const s of days){if(new Date(s+'T00:00:00').getTime()!==d.getTime())break;n++;d.setDate(d.getDate()-1)}return n})();
