 const finishWorkout=()=>{if(!active)return;save(d=>({...d,history:[{id:Date.now(),date:TODAY(),minutes:Math.max(1,Math.round((Date.now()-active.started)/60000)),exercises:todayPlan.map(p=>ex(p.exerciseId)?.name)} ,...d.history],active:null}),'บันทึกผลการฝึกแล้ว');setTimerOn(false);setPage('ความก้าวหน้า')};
 const nav=[['หน้าหลัก',LayoutDashboard],['ปฏิทิน',CalendarDays],['ท่าออกกำลังกาย',Dumbbell],['ความก้าวหน้า',BarChart3],['ตั้งค่า',Settings]];
